const item = $('Buscar Tarea Pendiente').item.json;
const systemPrompt = 'Sos un analista de investigación de mercado senior. Respondé siempre en español, en formato markdown, con información realista y honesta. Si no tenés certeza de un dato, aclaralo como estimación.';
const userPrompt = `Producto/Idea a investigar:
Nombre: ${item.ProjectName}
Descripción: ${item.Idea}

Generá tres secciones separadas EXACTAMENTE por estos marcadores (sin texto adicional antes o después de cada marcador):

===MARKET_RESEARCH===
(Análisis de mercado: tamaño, tendencias, comportamiento de usuarios, oportunidades)

===COMPETITOR_ANALYSIS===
(Análisis de al menos 3 competidores o productos similares: nombre, propuesta, precios, fortalezas, debilidades)

===USER_RESEARCH===
(Usuario objetivo, problemas actuales, necesidades, comportamiento)`;

const body = {
  model: 'openai/gpt-4o-mini',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ]
};

return [{ json: { ...item, requestBody: JSON.stringify(body) } }];

const item = $('Buscar Tarea Pendiente').item.json;
const response = $json;
const content = response.choices?.[0]?.message?.content || '';
const usage = response.usage || {};

function extract(marker, nextMarker) {
  const start = content.indexOf(marker);
  if (start === -1) return '_No se pudo generar esta sección._';
  const from = start + marker.length;
  const end = nextMarker ? content.indexOf(nextMarker, from) : content.length;
  return content.slice(from, end === -1 ? content.length : end).trim();
}

const marketResearchMd = extract('===MARKET_RESEARCH===', '===COMPETITOR_ANALYSIS===');
const competitorAnalysisMd = extract('===COMPETITOR_ANALYSIS===', '===USER_RESEARCH===');
const userResearchMd = extract('===USER_RESEARCH===', null);

const marketMd = `# Market Research — ${item.ProjectName}\n\n${marketResearchMd}\n`;
const competitorMd = `# Competitor Analysis — ${item.ProjectName}\n\n${competitorAnalysisMd}\n`;
const userMd = `# User Research — ${item.ProjectName}\n\n${userResearchMd}\n`;

const reportMd = `# Reporte de Etapa — AIQ-PF-02-MarketResearch\n\n` +
  `**Proyecto:** ${item.ProjectName} (${item.Slug})\n` +
  `**Fecha:** ${new Date().toISOString()}\n` +
  `**Modelo usado:** ${response.model || 'desconocido'}\n` +
  `**Tokens:** entrada ${usage.prompt_tokens ?? '?'} / salida ${usage.completion_tokens ?? '?'}\n\n` +
  `## Archivos generados\n- research/market-research.md\n- research/competitor-analysis.md\n- research/user-research.md\n\n` +
  `## Resumen\n${marketResearchMd.slice(0, 500)}${marketResearchMd.length > 500 ? '...' : ''}\n`;

return [{
  json: {
    ...item,
    marketMdB64: Buffer.from(marketMd, 'utf8').toString('base64'),
    competitorMdB64: Buffer.from(competitorMd, 'utf8').toString('base64'),
    userMdB64: Buffer.from(userMd, 'utf8').toString('base64'),
    reportMdB64: Buffer.from(reportMd, 'utf8').toString('base64')
  }
}];
